        return sub_arr == sub_arr[::-1]

    def min_changes_to_palindrome(sub_arr):
        changes = 0
        left, right = 0, len(sub_arr) - 1
        while left < right:
            if sub_arr[left] != sub_arr[right]:
                changes += 1
            left += 1
            right -= 1
        return changes

    if len(arr) <= 1:
        return 0

    middle = len(arr) // 2
    left_sub_arr = arr[:middle]
    right_sub_arr = arr[middle + len(arr) % 2:]

    if is_palindromic(arr):
        return 0
    else:
        return min_changes_to_palindrome(left_sub_arr) + min_changes_to_palindrome(right_sub_arr)

# Test cases
print(smallest_change([1,2,3,5,4,7,9,6]))  # Output: 4
print(smallest_change([1, 2, 3, 4, 3, 2, 2]))  # Output: 1
print(smallest_change([1, 2, 3, 2, 1]))  # Output: 0
